namespace NHAMBS.Cht

open System.IO
open FSharp.Data

/// Typed view of the key terms on a Canada Housing Trust offering circular.
///
/// The provider reads
/// `schema/cmhc-cht-offering-circular.provider.schema.json`, a flattened copy
/// of the real Draft 2020-12 schema. The copy is generated by
/// `generate-provider-schema.fsx` because FSharp.Data's schema reader does not
/// resolve `$ref`. The real schema remains the source of truth and is embedded
/// in this assembly for validation by `OfferingCircularSchema.validate`.
type OfferingCircular =
    JsonProvider<
        "",
        Schema="schema/cmhc-cht-offering-circular.provider.schema.json",
        EmbeddedResource="NHAMBS.Cht, NHAMBS.Cht.schema.cmhc-cht-offering-circular.provider.schema.json"
     >

[<RequireQualifiedAccess>]
module OfferingCircular =

    /// Parse JSON that is already known to match the offering circular schema.
    let parse (json: string) : OfferingCircular.Root = OfferingCircular.Parse json

    /// Validate JSON against the embedded schema, then parse it.
    let parseValidated (json: string) : Result<OfferingCircular.Root, ValidationError list> =
        match OfferingCircularSchema.validate json with
        | Error errors -> Error errors
        | Ok _ -> Ok(parse json)

    /// Load one offering circular JSON file, validate it, and parse it.
    let load (path: string) : Result<OfferingCircular.Root, ValidationError list> =
        File.ReadAllText path |> parseValidated

    /// Load a sequence of offering circular files. Each result keeps its path.
    let loadMany (paths: string seq) =
        paths |> Seq.map (fun path -> path, load path) |> Seq.toArray

    /// Load every `*.json` file directly under a directory.
    let loadDirectory (directory: string) =
        Directory.EnumerateFiles(directory, "*.json") |> loadMany

    /// Small projection that is useful when indexing a folder of circulars.
    let summary (circular: OfferingCircular.Root) =
        {|
            Series = circular.Series
            DocumentDate = circular.DocumentDate
            AggregatePrincipalAmount = circular.AggregatePrincipalAmount
            CouponKind = circular.Coupon.Kind
            MaturityDate = circular.MaturityDate
        |}
